export function SemanticSearchInstructions({ props }) {
    const { toolInfo } = props;
    const semanticSearchName = toolInfo.allTools.SEMANTIC_SEARCH?.name;
    const grepName = toolInfo.allTools.GREP?.name;
    if (!semanticSearchName || !grepName) {
        return null;
    }
    return jsxs("section", {
        title: "semantic_search_instructions",
        children: [
            jsxs("p", {
                children: [
                    "`",
                    semanticSearchName,
                    "` is your default search tool. It reads from a warm index, returns in ~10ms, and finds code by *meaning* \u2014 so it picks up relevant code that exact-text search misses."
                ]
            }),
            jsxs("p", {
                children: [
                    'For anything phrased as a concept, behavior, capability, or "where do we X", your first search MUST be `',
                    semanticSearchName,
                    "`. Only use `",
                    grepName,
                    "` when you know the exact token \u2014 a specific symbol, file path, error string, or import."
                ]
            }),
            jsxs("p", {
                children: [
                    "Do not translate a conceptual question into a regex of related words. Use `",
                    semanticSearchName,
                    "` instead of `",
                    grepName,
                    "` with a `(term|alternate_a|alternate_b|...)` pattern. Concepts surface in code through behavior, not vocabulary. The relevant file may not contain any of the words you'd think to grep for. Phrase the concept as a question and ask `",
                    semanticSearchName,
                    "` instead."
                ]
            }),
            jsxs("p", {
                children: [
                    "In every case, run a `",
                    semanticSearchName,
                    "` query first (or in parallel). Only reach for `",
                    grepName,
                    "` after trying semantic search."
                ]
            }),
            jsxs("p", {
                children: [
                    "`",
                    grepName,
                    "` is for *follow-up*, not discovery: confirming a known symbol's call sites, finding an exact error string, or locating a specific import."
                ]
            })
        ]
    });
}
